```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, state_read};

struct Node;

fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        // Enrichment fetch: one per call, keyed on the input's text.
        // The result is deliberately ignored (including transport failures),
        // so it cannot affect the node's output.
        let text = items
            .iter()
            .map(|i| i.text.as_str())
            .collect::<Vec<_>>()
            .join("\n");
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&text)
        );
        let _ = http_client::fetch(&url);

        // Drop every item whose id is already present in the 'seen' store.
        items
            .into_iter()
            .filter(|item| state_read::get(&item.id).is_none())
            .collect()
    }
}

export!(Node);
